'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),c=require('./native-fixtures-20261003.cjs').environment().ctx,plain=x=>JSON.parse(JSON.stringify(x)),results=[];
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
test('Wikisource逐卦64彖64大象384小象2用象與乾坤文言，來源修訂全部可追溯',()=>{const e=c.JYYijingWings.entries;assert.equal(e.length,64);assert.equal(e.reduce((s,e)=>s+e.lineImages.length,0),386);for(const [i,r] of e.entries()){assert.equal(r.number,i+1);assert(r.tuan&&r.greatImage&&r.lineImages.length>=6);assert(r.revision&&/^[a-f0-9]{64}$/.test(r.sourceSha256));}assert(e[0].tuan.includes('首出庶物'));assert(e[0].wenyan.includes('元者'));assert(e[1].wenyan.includes('坤'));});
test('屯之互剝綜蒙錯鼎：具名獨立卦形算例，補充納甲含世應伏神',()=>{const r=c.JYYijingCore.calculate({values:[7,8,8,8,7,8]});assert.equal(r.original.number,3);const v=r.complementaryViews.original;assert.equal(v.mutual.hexagram.number,23);assert.equal(v.overturned.hexagram.number,4);assert.equal(v.opposite.hexagram.number,50);for(const x of Object.values(v).filter(x=>x&&x.hexagram)){assert.equal(x.najia.length,6);assert(x.najia.some(l=>l.role==='世'));assert(x.najia.some(l=>l.role==='應'));}});
test('所有4096本卦／之卦組合保留朱子原主讀與易傳對應，不被互綜錯覆蓋',()=>{for(let code=0;code<64;code++)for(let changed=0;changed<64;changed++){const values=Array.from({length:6},(_,i)=>((code>>i)&1)?((changed>>i)&1?7:9):((changed>>i)&1?6:8)),r=c.JYYijingCore.calculate({values});assert.equal(r.original.code,code);assert.equal(r.changed.code,changed);assert(r.reading.selections.length);assert.equal(r.expositions.original.number,r.original.number);assert.equal(r.expositions.changed.number,r.changed.number);}});
test('两个125三才版本逐項完整，NTU表4分類總數獨立對照且不混作熊崎原文',()=>{const p=c.JYNameSancai.profiles,count=x=>Object.values(x).reduce((o,k)=>(o[k]=(o[k]||0)+1,o),{});assert.equal(Object.keys(p.CDI_125.rows).length,125);assert.equal(Object.keys(p.LINGZHAO_125.rows).length,125);assert.deepEqual(plain(count(p.CDI_125.rows)),{'吉':9,'最吉':16,'凶':67,'半吉':2,'平吉':12,'最凶':19});assert.deepEqual(plain(count(p.LINGZHAO_125.rows)),{'吉':28,'平':41,'平下':41,'次吉':9,'平上':6});assert.equal(c.JYNameSancai.audit.bothPositive,25);assert(c.JYNameSancai.audit.empiricalStudy.includes('TER473-4')); assert(c.JYNameSancai.audit.classification.includes('not-original'));});
test('姓名比較與JSON沿用選定三才版本，異版本保留不當多票',()=>{for(const profile of ['CDI_125','LINGZHAO_125']){const r=c.JYNameEngine.analyze({surname:'陳',given:'弘林',birthYear:1983,sancaiProfile:profile});assert.equal(r.fiveGrids.sanCai.profile,profile);assert.equal(r.fiveGrids.sanCai.versions.length,3);assert(r.fiveGrids.sanCai.source);assert(c.JYNamePrompt.build(r).includes(profile));}});
test('增刪章8女婿醫藥父母文契姊丈妹夫逐項取用，姑姨重義保留分支',()=>{for(const [q,k]of [['女婿近期如何','子孫'],['藥物是否合用','子孫'],['房契能順利辦好嗎','父母'],['我的妹夫近況','世'],['妻占丈夫功名','官鬼']])assert(c.JYLiuyaoCore.focusFor(q,'auto').candidates.includes(k));assert.deepEqual(plain(c.JYLiuyaoCore.focusFor('我的姑姑近況','auto').candidates).sort(),['兄弟','父母']);assert.equal(c.JYLiuyaoCore.focusFor('???','auto').status,'unresolved');});
test('六爻寒露交節瞬間前後分段曆法實算，不只附提醒文字',()=>{const date=c.JYLiuyaoCore.calendar({year:2026,month:10,day:2,hour:12,minute:0,timezoneOffset:8}),r=c.JYLiuyaoCore.calculate({values:[6,7,8,9,7,8],calendar:date,question:'未來7天工作的變化'}),d=r.interpretation.timing.inspectedDays.find(d=>d.date==='2026-10-08');assert(d);assert.equal(d.segments.length,2);assert.equal(d.segments[0].monthBranch,'酉');assert.equal(d.segments[1].monthBranch,'戌');assert.equal(d.segments[0].endExclusive,'2026-10-08T06:29:17.000Z');assert.equal(d.segments[0].endExclusive,d.segments[1].start);});
test('六爻00／23日界與無效日期驗證，遠期窗不造首次出旬',()=>{const date=c.JYLiuyaoCore.calendar({year:2026,month:10,day:2,hour:12,minute:0,timezoneOffset:8}),a=c.JYLiuyaoCore.calendarSegments('2026-10-08',date),b=c.JYLiuyaoCore.calendarSegments('2026-10-08',{...date,dayBoundaryMode:'ZI_HOUR_23'});assert.equal(Date.parse(a[0].start)-Date.parse(b[0].start),3600000);assert.throws(()=>c.JYLiuyaoCore.parseWindow('',date,{end:'2026-02-30'}));});
test('十干兩版四化全部40項：壬科差別真正作用於生年各運限宮干飛化',()=>{const modern=c.JYZiweiCompletion.resolve({}),old=c.JYZiweiCompletion.resolve({sihuaProfile:'QUANSHU_XINGGE'});for(const g of Array.from('甲乙丙丁戊己庚辛壬癸'))for(const h of ['祿','權','科','忌'])if(g==='壬'&&h==='科'){assert.equal(modern.table[g][h],'左輔');assert.equal(old.table[g][h],'天府');}else assert.equal(modern.table[g][h],old.table[g][h]);const options={minute:55,sihuaProfile:'QUANSHU_XINGGE',referenceDate:'2032-10-02T04:00:00Z'},z=c.computeZiwei(1982,8,25,14,'male',options);assert(z,c._jyZiweiError);assert.equal(z.calculationPolicy.sihuaProfile,'QUANSHU_XINGGE');assert(z.sihua.some(h=>h.star==='天府'&&h.hua==='化科'));assert(z.getLiuNianZw(2032).hua.some(h=>h.star==='天府'&&h.hua==='化科'));assert(z.feiGongHua.filter(p=>p.gan==='壬').every(p=>p.ke.star==='天府'));});
test('紫微48實際飛化、48閉合路徑、18星、六對宮及祿忌權科數組全部保留',()=>{const z=c.computeZiwei(1983,8,25,14,'male',{minute:55,referenceDate:'2026-10-02T04:00:00Z'});assert(z,c._jyZiweiError);const n=z.northern;assert.equal(n.flights.length,48);assert.equal(n.paths.length,48);assert.equal(n.starPlacements.length,18);assert.equal(n.opposingAxes.length,6);for(const r of n.paths){assert(r.steps.length<=12&&r.steps.length>0);for(let i=1;i<r.steps.length;i++)assert.equal(n.flights[r.steps[i-1]].toBranch,n.flights[r.steps[i]].fromBranch);assert.equal(r.termination,'cycle');}assert(n.symbolPairs.every(r=>r.sum===5));const a=c.JYNativeAnalysis.analyze('ziwei',z);for(const p of [a.layers.decade,a.layers.annual,...a.layers.months,a.layers.daily,a.layers.hourly].filter(Boolean))assert.equal(p.northern.flights.length,48);assert(c.JYNativeAnalysis.prompt('ziwei',z,'分析2026',{supplement:true}).includes('northern'));});
test('自訂四化必須完整有名有來源，兩張不同版本盤不污染彼此閉包',()=>{assert.throws(()=>c.JYZiweiCompletion.resolve({sihuaProfile:'CUSTOM',sihuaCustom:{}}));const a=c.computeZiwei(1982,8,25,14,'male',{minute:55,sihuaProfile:'IZTRO_261'}),b=c.computeZiwei(1982,8,25,14,'male',{minute:55,sihuaProfile:'QUANSHU_XINGGE'});assert(a&&b);assert(a.getLiuNianZw(2032).hua.some(x=>x.star==='左輔'&&x.hua==='化科'));assert(b.getLiuNianZw(2032).hua.some(x=>x.star==='天府'&&x.hua==='化科'));});
test('楚天雲闊2018具名部分盤例：癸酉貪狼忌轉巨門權、己巳武曲祿聯動辰戊天機忌',()=>{
 const G=Array.from('甲乙丙丁戊己庚辛壬癸'),Z=Array.from('子丑寅卯辰巳午未申酉戌亥'),names=['命宮','兄弟','父母','福德','田宅','官祿','奴僕','遷移','疾厄','財帛','子女','夫妻'];
 const palaces=Z.map((branch,i)=>({branch,name:names[i],gan:G[i%10],stars:[]}));
 // Source supplies these placements only; remaining stars are synthetic chart scaffolding, not a reconstructed birth chart.
 const placements={武曲:'亥',文曲:'辰',貪狼:'卯',巨門:'辰',天機:'寅',天梁:'午'};
 const all=['紫微','天機','太陽','武曲','天同','廉貞','天府','太陰','貪狼','巨門','天相','天梁','七殺','破軍','左輔','右弼','文昌','文曲'];
 all.forEach((name,i)=>palaces.find(p=>p.branch===(placements[name]||Z[i%12])).stars.push({name}));
 const sihua=[['祿','武曲'],['權','貪狼'],['科','天梁'],['忌','文曲']].map(([h,star])=>({hua:'化'+h,star,palaceBranch:placements[star]}));
 const n=c.JYZiweiCompletion.graph({palaces,sihua,birthInput:{sihuaProfile:'IZTRO_261'}});
 const a=n.transitions.find(t=>t.incoming.fromBranch==='酉'&&t.incoming.kind==='忌'&&t.birthTransformation.star==='貪狼');assert(a);assert.equal(a.transferred.kind,'權');assert.equal(a.transferred.star,'巨門');assert.equal(a.transferred.toBranch,'辰');
 const b=n.transitions.find(t=>t.rule==='祿又祿則忌又忌'&&t.incoming.fromBranch==='巳');assert(b);assert.equal(b.transferred.fromBranch,'辰');assert.equal(b.transferred.star,'天機');assert.equal(b.transferred.toBranch,'寅');assert(n.sourceAudit.textualVariant);
});
